import{isUnanswerableResponseError}from"#channel/session-not-active-error.js";const INACTIVE_REQUEST_NOTICE=`This request is no longer active. Send a new message to start again.`,INACTIVE_PROMPT_LABEL=`No longer active`;async function respondOrRetireInactivePrompt(e,t,n){try{return await e(),{outcome:`delivered`}}catch(e){if(!isUnanswerableResponseError(e))return n.error(`input response delivery failed`,{error:e}),{outcome:`failed`,error:e};n.warn(`input response reached no active session`,{error:e})}return{outcome:`inactive`,retirement:t.retirePrompt(INACTIVE_PROMPT_LABEL).catch(e=>n.error(`inactive prompt edit failed`,{error:e}))}}export{INACTIVE_PROMPT_LABEL,INACTIVE_REQUEST_NOTICE,respondOrRetireInactivePrompt};